# >>> CHOICES
_choice_range() {
    git rev-parse --git-dir >/dev/null 2>&1 || return 0
    printf 'HEAD\n'
    git for-each-ref --count=500 --format='%(refname:short)' refs/heads refs/tags refs/remotes 2>/dev/null
}

_choice_skip_commit() {
    git rev-parse --git-dir >/dev/null 2>&1 || return 0
    git log --max-count=100 --format='%h%x09%s' 2>/dev/null
}

_choice_tag() {
    git rev-parse --git-dir >/dev/null 2>&1 || return 0
    git for-each-ref --count=500 --format='%(refname:short)' refs/tags 2>/dev/null
}
